parameters.text:
=You are a B2B sales qualification analyst for an AI automation agency.

Analyze the following lead.

Lead Information:
Name: {{ $json.lead.fullName }}
Email: {{ $json.lead.email }}
Company: {{ $json.lead.company }}
Website: {{ $json.lead.website }}
Job Title: {{ $json.lead.jobTitle }}
Industry: {{ $json.lead.industry }}
Company Size: {{ $json.lead.companySize }}
Need: {{ $json.lead.need }}
Budget: {{ $json.lead.budget }}
Timeline: {{ $json.lead.timeline }}
Message: {{ $json.lead.message }}

Ideal Customer Profile:
- Target company size: 10–500 employees
- Target decision makers: Founder, CEO, COO, CTO, Head of Operations, or similar senior roles
- Preferred budget: $1,000 or more
- Strong preference for a clear AI or automation requirement
- Stronger prospects have a specific business problem and a near-term implementation timeline

Determine:
1. Whether the lead fits the ICP
2. Buying intent
3. Budget level
4. Decision-making authority
5. Strength of business need
6. Project timeline
7. Key pain points
8. Recommended solution
9. A concise qualification summary
10. The single best next action from this fixed list only: Call Immediately, Send Pricing, Schedule Demo, Send Brochure, Nurture 30 Days, Disqualify

Do not invent information.
If something cannot be determined from the provided information, use "Unknown".

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "ideal_customer_fit": {"type": "string", "enum": ["Yes", "No", "Unknown"]},
    "buying_intent": {"type": "string", "enum": ["High", "Medium", "Low", "Unknown"]},
    "budget_level": {"type": "string", "enum": ["High", "Medium", "Low", "Unknown"]},
    "authority_level": {"type": "string", "enum": ["High", "Medium", "Low", "Unknown"]},
    "need_level": {"type": "string", "enum": ["High", "Medium", "Low", "Unknown"]},
    "timeline": {"type": "string", "enum": ["Immediate", "Within 1 Month", "1–3 Months", "3–6 Months", "6+ Months", "Unknown"]},
    "pain_points": {"type": "array", "items": {"type": "string"}},
    "next_best_action": {"type": "string", "enum": ["Call Immediately", "Send Pricing", "Schedule Demo", "Send Brochure", "Nurture 30 Days", "Disqualify"]},
    "recommended_solution": {"type": "string"},
    "qualification_summary": {"type": "string"}
  },
  "required": ["ideal_customer_fit", "buying_intent", "budget_level", "authority_level", "need_level", "timeline", "pain_points", "next_best_action", "recommended_solution", "qualification_summary"]
}

parameters.jsCode:
const aiResult = $input.first().json;

// Get original lead from Validate & Normalize node
const original = $('Validate & Normalize').first().json;

return [
  {
    json: {
      lead: original.lead,
      submittedAt: original.submittedAt,
      qualification: aiResult.output
    }
  }
];

const input = $input.first().json;

// Helper
const clean = (value) => {
  if (value === undefined || value === null) return '';
  return String(value).trim();
};

// Read form fields
const firstName = clean(input["First Name"]);
const lastName = clean(input["Last Name"]);
const email = clean(input["Email"]).toLowerCase();
const phone = clean(input["Phone"]);
const company = clean(input["Company"]);
const website = clean(input["Website"]);
const jobTitle = clean(input["Job Title"]);
const industry = clean(input["Industry"]);
const companySize = clean(input["Company Size"]);
const need = clean(input["What do you need?"]);
const budget = clean(input["Budget"]);
const timeline = clean(input["Timeline"]);
const message = clean(input["Message"]);
const leadSource = clean(input["Lead Source"]);

// Required-field validation
const errors = [];

if (!firstName) errors.push("First Name is missing");
if (!lastName) errors.push("Last Name is missing");
if (!email) errors.push("Email is missing");
if (!company) errors.push("Company is missing");
if (!jobTitle) errors.push("Job Title is missing");
if (!industry) errors.push("Industry is missing");
if (!companySize) errors.push("Company Size is missing");
if (!need) errors.push("What do you need? is missing");
if (!budget) errors.push("Budget is missing");
if (!timeline) errors.push("Timeline is missing");
if (!message) errors.push("Message is missing");

// Basic email validation
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

if (email && !emailValid) {
  errors.push("Invalid email format");
}

// Return normalized lead
return [
  {
    json: {
      lead: {
        firstName,
        lastName,
        fullName: `${firstName} ${lastName}`.trim(),
        email,
        phone,
        company,
        website,
        jobTitle,
        industry,
        companySize,
        need,
        budget,
        timeline,
        message,
        leadSource
      },
      validation: {
        valid: errors.length === 0,
        errors
      },
      submittedAt: input.submittedAt || new Date().toISOString()
    }
  }
];

const input = $input.first().json;

const q = input.qualification;
const lead = input.lead;

let score = 0;

// ICP Fit — 20
if (q.ideal_customer_fit === "Yes") {
  score += 20;
}

// Authority — 15
const authorityPoints = {
  High: 15,
  Medium: 10,
  Low: 5,
  Unknown: 0
};
score += authorityPoints[q.authority_level] || 0;

// Budget — 20
const budgetPoints = {
  High: 20,
  Medium: 12,
  Low: 5,
  Unknown: 0
};
score += budgetPoints[q.budget_level] || 0;

// Need — 20
const needPoints = {
  High: 20,
  Medium: 12,
  Low: 5,
  Unknown: 0
};
score += needPoints[q.need_level] || 0;

// Timeline — 15
const timelinePoints = {
  "Immediate": 15,
  "Within 1 Month": 15,
  "1–3 Months": 12,
  "3–6 Months": 8,
  "6+ Months": 3,
  "Unknown": 0
};
score += timelinePoints[q.timeline] || 0;

// Problem clarity — 10
if (Array.isArray(q.pain_points) && q.pain_points.length > 0) {
  score += 10;
}

// Lead tier
let leadTier;

if (score >= 80) {
  leadTier = "HOT";
} else if (score >= 50) {
  leadTier = "WARM";
} else {
  leadTier = "COLD";
}

return [
  {
    json: {
      lead,
      qualification: q,
      leadScore: score,
      leadTier
    }
  }
];

const input = $input.first().json;

const aiPainPoints = input.qualification?.pain_points || [];

const painPointText = aiPainPoints.join(" ").toLowerCase();

const mappedPainPoints = [];

if (
  painPointText.includes("manual") ||
  painPointText.includes("inquiries manually")
) {
  mappedPainPoints.push("Manual Processes");
}

if (
  painPointText.includes("customer") ||
  painPointText.includes("support") ||
  painPointText.includes("inquiries")
) {
  mappedPainPoints.push("Customer Support");
}

if (
  painPointText.includes("high volume") ||
  painPointText.includes("hundreds") ||
  painPointText.includes("large volume")
) {
  mappedPainPoints.push("High Support Volume");
}

if (
  painPointText.includes("repetitive") ||
  painPointText.includes("repetitive tasks")
) {
  mappedPainPoints.push("Repetitive Tasks");
}

if (
  painPointText.includes("lead") ||
  painPointText.includes("lead management")
) {
  mappedPainPoints.push("Lead Management");
}

if (
  painPointText.includes("data entry") ||
  painPointText.includes("data-entry")
) {
  mappedPainPoints.push("Data Entry");
}

if (
  painPointText.includes("workflow") ||
  painPointText.includes("inefficien")
) {
  mappedPainPoints.push("Workflow Inefficiency");
}

// Remove duplicates
const uniquePainPoints = [...new Set(mappedPainPoints)];

if (uniquePainPoints.length === 0) {
  uniquePainPoints.push("Other");
}

return [
  {
    json: {
      ...input,
      mappedPainPoints: uniquePainPoints
    }
  }
];

const hubspot = $input.first().json;
const original = $('Map Pain Points').first().json;

return [
  {
    json: {
      ...original,
      hubspot
    }
  }
];

const input = $input.first().json;

const tier = input.leadTier;
const industry = input.lead.industry;
const q = input.qualification;

let route;
let routingReason;

if (tier === "HOT" && industry === "SaaS") {
  route = "HOT_SaaS";
  routingReason = "Routed to SaaS Sales Team — HOT tier (score " + input.leadScore + "/100), industry: SaaS. Buying intent: " + q.buying_intent + ", budget: " + q.budget_level + ", authority: " + q.authority_level + ".";
} else if (tier === "HOT" && industry === "E-commerce") {
  route = "HOT_Ecommerce";
  routingReason = "Routed to E-commerce Sales Team — HOT tier (score " + input.leadScore + "/100), industry: E-commerce. Buying intent: " + q.buying_intent + ", budget: " + q.budget_level + ", authority: " + q.authority_level + ".";
} else if (tier === "HOT" && industry === "Professional Services") {
  route = "HOT_Professional_Services";
  routingReason = "Routed to Professional Services Team — HOT tier (score " + input.leadScore + "/100), industry: Professional Services. Buying intent: " + q.buying_intent + ", budget: " + q.budget_level + ", authority: " + q.authority_level + ".";
} else if (tier === "HOT") {
  route = "HOT_General";
  routingReason = "Routed to General Sales — HOT tier (score " + input.leadScore + "/100), industry: " + industry + " (no dedicated team yet). Buying intent: " + q.buying_intent + ", budget: " + q.budget_level + ", authority: " + q.authority_level + ".";
} else if (tier === "WARM") {
  route = "WARM";
  routingReason = "Routed to Nurture — WARM tier (score " + input.leadScore + "/100). Need level: " + q.need_level + ", timeline: " + q.timeline + ". Not yet sales-ready.";
} else if (tier === "COLD") {
  route = "COLD";
  routingReason = "Routed to Marketing Nurture — COLD tier (score " + input.leadScore + "/100). ICP fit: " + q.ideal_customer_fit + ", budget: " + q.budget_level + ". Low near-term priority.";
} else {
  route = "UNROUTED";
  routingReason = "UNROUTED — leadTier value \"" + tier + "\" did not match any known tier. Manual review required.";
}

return [
  {
    json: {
      ...input,
      route,
      routingReason
    }
  }
];

