const dupItems = $input.all();
const isDuplicate = dupItems.length > 0 && dupItems[0].json.Email !== undefined && dupItems[0].json.Email !== '';

const original = $('Is Lead Valid?').first().json;

if (!isDuplicate) {
  return [{ json: { ...original, isDuplicate: false } }];
} else {
  return [{ json: { isDuplicate: true, lead: original.lead } }];
}

