const input = $input.first().json;

// TODO: replace these with real per-team inboxes / Telegram chat IDs.
// Every route currently points to your own verified inbox as a safe default
// so nothing silently fails - but real team routing needs real addresses here.
const ROUTE_CONFIG = {
  HOT_SaaS: { email: 'user@example.com', team: 'SaaS Sales Team' },
  HOT_Ecommerce: { email: 'user@example.com', team: 'E-commerce Sales Team' },
  HOT_Professional_Services: { email: 'user@example.com', team: 'Professional Services Team' },
  HOT_General: { email: 'user@example.com', team: 'General Sales' },
  WARM: { email: 'user@example.com', team: 'Nurture Team' },
  COLD: { email: 'user@example.com', team: 'Marketing Nurture' },
  UNROUTED: { email: 'user@example.com', team: 'Manual Review (Unrouted)' }
};

const target = ROUTE_CONFIG[input.route] || ROUTE_CONFIG.UNROUTED;

return [
  {
    json: {
      ...input,
      notifyEmail: target.email,
      assignedTeam: target.team
    }
  }
];
